<?php
 declare(strict_types=1); namespace Slim\Http\Factory; use Psr\Http\Message\ResponseFactoryInterface; use Psr\Http\Message\ResponseInterface; use Psr\Http\Message\StreamFactoryInterface; use Slim\Http\Response; class DecoratedResponseFactory implements ResponseFactoryInterface { protected $responseFactory; protected $streamFactory; public function __construct(ResponseFactoryInterface $responseFactory, StreamFactoryInterface $streamFactory) { $this->responseFactory = $responseFactory; $this->streamFactory = $streamFactory; } public function createResponse(int $code = 200, string $reasonPhrase = ''): ResponseInterface { $response = $this->responseFactory->createResponse($code, $reasonPhrase); return new Response($response, $this->streamFactory); } } 